+++ b/tests/config_api_test.rs
@@ -111,3 +111,27 @@ fn interpolation_context_workflow() {
     let result = resolve_string("Environment: ${RAILS_ENV}", &ctx).unwrap();
     assert_eq!(result, "Environment: development");
 }
+
+#[test]
+fn invalid_config_rejected_not_silently_defaulted() {
+    let temp = TempDir::new().unwrap();
+    let bivvy_dir = temp.path().join(".bivvy");
+    fs::create_dir_all(&bivvy_dir).unwrap();
+
+    // Config with typo: "settigns" instead of "settings"
+    fs::write(
+        bivvy_dir.join("config.yml"),
+        r#"
+app_name: TestApp
+settigns:
+  default_output: quiet
+"#,
+    )
+    .unwrap();
+
+    let result = load_merged_config(temp.path());
+    assert!(
+        result.is_err(),
+        "config with typo should fail, not silently use defaults"
+    );
+}

